mapper.select:
SELECT operNo, operDbuser, operNameHex FROM (
    SELECT USER_ID AS operNo, DB_USER AS operDbuser,
           RAWTOHEX(TRIM(USER_NAME)) AS operNameHex, ROWNUM AS rn
    FROM users
    WHERE (USER_ID LIKE '%' || #{kw} || '%'
        OR DB_USER LIKE '%' || #{kw} || '%'
        OR RAWTOHEX(USER_NAME) LIKE '%' || #{kwHex} || '%')
      AND ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}
